/**
 * frontend/src/auth_service.js - SERVICE D'AUTHENTIFICATION
 * ✅ JWT tokens
 * ✅ localStorage persistence
 * ✅ Interceptors axios
 */

import axios from 'axios';

const API_BASE_URL = 'http://localhost:8000';

class AuthService {
  constructor() {
    this.api = axios.create({
      baseURL: API_BASE_URL,
      timeout: 20000,
    });

    this.setupInterceptors();
    this.initialize();
  }

  setupInterceptors() {
    this.api.interceptors.request.use(
      (config) => {
        const token = localStorage.getItem('access_token');
        if (token) {
          config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
      },
      (error) => Promise.reject(error)
    );

    this.api.interceptors.response.use(
      (response) => response,
      (error) => {
        if (error.response?.status === 401) {
          localStorage.clear();
          window.location.href = '/';
        }
        return Promise.reject(error);
      }
    );
  }

  initialize() {
    const token = localStorage.getItem('access_token');
    const user = localStorage.getItem('user');

    if (token && user) {
      this.api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
    }
  }

  async login(username, password) {
    try {
      const response = await this.api.post('/auth/login/', {
        username,
        password,
      });

      const { access, refresh, user } = response.data;

      localStorage.setItem('access_token', access);
      localStorage.setItem('refresh_token', refresh);
      localStorage.setItem('user', JSON.stringify(user));

      this.api.defaults.headers.common['Authorization'] = `Bearer ${access}`;

      console.log('✅ [AUTH] Login successful:', user.username);

      return {
        success: true,
        user,
      };
    } catch (error) {
      const message = error.response?.data?.error || 'Erreur de connexion';
      console.error('❌ [AUTH] Login failed:', message);
      return {
        success: false,
        error: message,
      };
    }
  }

  async register(username, email, password, passwordConfirm, firstName = '') {
    try {
      const response = await this.api.post('/auth/register/', {
        username,
        email,
        password,
        password_confirm: passwordConfirm,
        first_name: firstName,
      });

      const { access, refresh, user } = response.data;

      localStorage.setItem('access_token', access);
      localStorage.setItem('refresh_token', refresh);
      localStorage.setItem('user', JSON.stringify(user));

      this.api.defaults.headers.common['Authorization'] = `Bearer ${access}`;

      console.log('✅ [AUTH] Registration successful:', user.username);

      return {
        success: true,
        user,
      };
    } catch (error) {
      const message = error.response?.data?.error || 'Erreur d\'inscription';
      console.error('❌ [AUTH] Registration failed:', message);
      return {
        success: false,
        error: message,
      };
    }
  }

  async logout() {
    try {
      const refreshToken = localStorage.getItem('refresh_token');

      if (refreshToken) {
        await this.api.post('/auth/logout/', {
          refresh: refreshToken,
        });
      }

      localStorage.clear();
      delete this.api.defaults.headers.common['Authorization'];

      console.log('✅ [AUTH] Logout successful');

      return { success: true };
    } catch (error) {
      console.error('❌ [AUTH] Logout error:', error);
      localStorage.clear();
      return { success: true };
    }
  }

  async refreshToken() {
    try {
      const refreshToken = localStorage.getItem('refresh_token');

      if (!refreshToken) {
        throw new Error('No refresh token');
      }

      const response = await this.api.post('/auth/refresh/', {
        refresh: refreshToken,
      });

      const { access } = response.data;

      localStorage.setItem('access_token', access);
      this.api.defaults.headers.common['Authorization'] = `Bearer ${access}`;

      console.log('✅ [AUTH] Token refreshed');

      return { success: true };
    } catch (error) {
      console.error('❌ [AUTH] Token refresh failed:', error);
      localStorage.clear();
      return { success: false };
    }
  }

  isAuthenticated() {
    const token = localStorage.getItem('access_token');
    return !!token;
  }

  getUser() {
    const user = localStorage.getItem('user');
    return user ? JSON.parse(user) : null;
  }

  getToken() {
    return localStorage.getItem('access_token');
  }
}

export default new AuthService();
